import type { ContentPageId } from '@/config/site';
import type { HomeFile, PageFile, PageMeta } from './types';

// Generated by `npm run content` (git-ignored). Each page is a lazy chunk.
const files = import.meta.glob<unknown>('./generated/*.json', { import: 'default' });

function load<T>(key: string, what: string): Promise<T> {
  const loader = files[`./generated/${key}.json`];
  if (!loader) {
    return Promise.reject(new Error(`No generated ${what}. Run \`npm run content\`.`));
  }
  return loader() as Promise<T>;
}

export function loadPage(id: ContentPageId): Promise<PageFile> {
  return load<PageFile>(id, `content for "${id}"`);
}

/** The outline of every page, for the Home diagram. */
export function loadHome(): Promise<HomeFile> {
  return load<HomeFile>('home', 'home outline');
}

/** The small file with the title, lead and stats of every page, for the heroes. */
export function loadMeta(): Promise<Record<string, PageMeta>> {
  return load<Record<string, PageMeta>>('meta', 'page meta');
}
